    /// </summary>
    [Theory]
    [MemberData(nameof(Seeds))]
    public void RandomSession_ChainedOperations_MatchSpec_AndStockIsConserved(int seed)
    {
        var random = new Random(seed);
        var jammed = AllJams[random.Next(AllJams.Length)];
